import{_ as i,C as o,c as r,o as a,a2 as s,b as l,w as t,a as c,G as u,a3 as d}from"./chunks/framework.DkPtUiZm.js";const C=JSON.parse('{"title":"Frontières entre paquets","description":"","frontmatter":{},"headers":[],"relativePath":"fondations/frontieres-paquets.md","filePath":"fondations/frontieres-paquets.md","lastUpdated":1790233006000}'),p={name:"fondations/frontieres-paquets.md"};function m(q,e,h,f,g,b){const n=o("Mermaid");return a(),r("div",null,[e[1]||(e[1]=s('<h1 id="frontieres-entre-paquets" tabindex="-1">Frontières entre paquets <a class="header-anchor" href="#frontieres-entre-paquets" aria-label="Permalink to &quot;Frontières entre paquets&quot;">​</a></h1><h2 id="la-question-qui-tranche" tabindex="-1">La question qui tranche <a class="header-anchor" href="#la-question-qui-tranche" aria-label="Permalink to &quot;La question qui tranche&quot;">​</a></h2><p>Huit paquets, et une seule règle pour savoir où va une chose : <strong>à quel public s&#39;adresse-t-elle ?</strong> Pas « est-ce partagé ? » — tout finit par être partagé, et un paquet nommé d&#39;après ce critère devient l&#39;endroit où l&#39;on range ce qu&#39;on ne sait pas classer.</p><p>Un exemple qui rend la règle concrète. Le vocabulaire de rendu — <code>ComponentTone</code>, <code>ComponentSize</code>, <code>ComponentVariant</code> — tient en soixante-cinq lignes et sert à vingt-cinq fichiers. Le client HTTP en fait mille huit cents et sert à trois. Dans le même paquet, copier un <code>Badge</code> depuis le registre obligerait à installer un client HTTP complet, avec ses greffons, ses transports, son stockage de jetons et sa logique de réessai. Deux publics, deux paquets.</p><h2 id="ou-va-quoi" tabindex="-1">Où va quoi <a class="header-anchor" href="#ou-va-quoi" aria-label="Permalink to &quot;Où va quoi&quot;">​</a></h2>',5)),(a(),l(d,null,{default:t(()=>[u(n,{id:"mermaid-15",class:"mermaid",graph:"flowchart%20LR%0A%20%20V%5B%22vocabulaire%3Cbr%2F%3Eton%2C%20taille%2C%20variante%22%5D%20--%3E%20TK%5B%22%40sia-ui%2Ftokens%3Cbr%2F%3E%3Ci%3Edes%20valeurs%3C%2Fi%3E%22%5D%0A%20%20T%5B%22toneClass%22%5D%20--%3E%20U%5B%22%40sia-ui%2Futils%3Cbr%2F%3E%3Ci%3Eun%20nom%20de%20classe%3C%2Fi%3E%22%5D%0A%20%20F%5B%22FormAdapter%22%5D%20--%3E%20H%5B%22%40sia-ui%2Fheadless%3Cbr%2F%3E%3Ci%3Eavec%20useLocalForm%3C%2Fi%3E%22%5D%0A%20%20R%5B%22RegistryItem%22%5D%20--%3E%20RG%5B%22%40sia-ui%2Fregistry%3Cbr%2F%3E%3Ci%3Esa%20propre%20forme%3C%2Fi%3E%22%5D%0A%20%20A%5B%22client%20HTTP%22%5D%20--%3E%20AP%5B%22%40sia-ui%2Fapi%3Cbr%2F%3E%3Ci%3Epaquet%20%C3%A0%20part%3C%2Fi%3E%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s(`<ul><li>Le <strong>vocabulaire</strong> est fait de valeurs — <code>ComponentTone</code> est un nom que chaque plateforme traduit. Il vit auprès des couleurs et des espacements.</li><li><strong><code>toneClass</code></strong> ne l&#39;a pas suivi, alors qu&#39;il manipule le même vocabulaire : il fabrique un nom de classe CSS, donc une convention de rendu. Le natif traduira le même ton en objet de style et ne l&#39;appellera jamais. Il vit dans <code>@sia-ui/utils</code>, auprès de <code>cn</code>.</li><li>Le <strong>contrat de formulaire</strong> vit avec <code>useLocalForm</code>, son implémentation de référence. Les deux vont ensemble et ni l&#39;un ni l&#39;autre ne touche le DOM.</li><li><strong><code>RegistryItem</code></strong> décrit une entrée du registre : c&#39;est la forme du paquet <code>registry</code>, qui n&#39;a aucune raison de dépendre d&#39;un paquet d&#39;interface pour décrire un fichier à copier.</li><li>Le <strong>client HTTP</strong> est <code>@sia-ui/api</code>. Il n&#39;a aucun rapport avec l&#39;interface : ni React, ni DOM, ni tokens. Il est utilisable seul, dans une application native, un script Node, un backend-for-frontend.</li></ul><p>Ce qui ne se partage pas non plus : <strong>la forme des props.</strong> Le web étend <code>HTMLAttributes</code> et prend <code>className</code>, le natif étend <code>ViewProps</code> et prend <code>style</code>. Chaque composant déclare donc ses props chez lui — voir <a href="./source-unique.html">31 — Source unique</a>.</p><h2 id="la-pile" tabindex="-1">La pile <a class="header-anchor" href="#la-pile" aria-label="Permalink to &quot;La pile&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@sia-ui/tokens        valeurs : couleurs, espacements, mouvement, vocabulaire</span></span>
<span class="line"><span>@sia-ui/utils         fonctions sans dépendance</span></span>
<span class="line"><span>@sia-ui/api           client HTTP — indépendant de l&#39;interface</span></span>
<span class="line"><span>@sia-ui/headless      comportement, avec React, sans plateforme</span></span>
<span class="line"><span>@sia-ui/react         primitives de runtime DOM</span></span>
<span class="line"><span>@sia-ui/react-web     composants DOM</span></span>
<span class="line"><span>@sia-ui/react-native  composants natifs, à venir</span></span></code></pre></div><p><code>react-native</code> dépendra <strong>exactement du même ensemble</strong> que <code>react-web</code> : <code>tokens</code>, <code>utils</code>, <code>headless</code>, plus <code>api</code> s&#39;il en a besoin.</p><h2 id="ce-que-la-regle-interdit" tabindex="-1">Ce que la règle interdit <a class="header-anchor" href="#ce-que-la-regle-interdit" aria-label="Permalink to &quot;Ce que la règle interdit&quot;">​</a></h2><ul><li>Un composant de <code>react-web</code> n&#39;importe rien depuis un autre dossier que le sien : la CLI ne sert que <code>components/&lt;Nom&gt;/</code>, et un import vers <code>../../</code> arrive cassé chez l&#39;utilisateur. C&#39;est vérifié par <code>packages/cli/src/install.test.ts</code>.</li><li><code>headless</code> n&#39;importe pas <code>react-web</code>. <code>tokens</code> n&#39;importe pas React.</li><li>Un réexport n&#39;est pas une frontière : un dossier qui ne fait que réexporter un paquet voisin est une indirection, pas une couche.</li></ul><h2 id="la-prochaine-couture" tabindex="-1">La prochaine couture <a class="header-anchor" href="#la-prochaine-couture" aria-label="Permalink to &quot;La prochaine couture&quot;">​</a></h2><p><code>@sia-ui/tokens</code> mélange des valeurs brutes — couleurs, espacements, vocabulaire — et de la génération CSS : <code>toCssVariables</code>, <code>themeVariables</code>. Le natif voudra les premières sans la seconde. Ce n&#39;est pas bloquant, le tree-shaking s&#39;en charge, mais c&#39;est à examiner le jour où le paquet natif existera.</p>`,9))])}const _=i(p,[["render",m]]);export{C as __pageData,_ as default};
